**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <iomanip>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    vector<int> T;
    int x;
    while (plik >> x) T.push_back(x);
    int n = T.size();

    int liczbaSerii = 0;
    int sumaDlugosci = 0;
    int maxDl = 0, maxStart = 0;
    int curDl = 1, curStart = 0;

    for (int i = 1; i < n; i++) {
        if (T[i] < T[i - 1]) {
            curDl++;
        } else {
            if (curDl >= 2) {
                liczbaSerii++;
                sumaDlugosci += curDl;
                if (curDl > maxDl) {
                    maxDl = curDl;
                    maxStart = curStart;
                }
            }
            curDl = 1;
            curStart = i;
        }
    }
    if (curDl >= 2) {
        liczbaSerii++;
        sumaDlugosci += curDl;
        if (curDl > maxDl) {
            maxDl = curDl;
            maxStart = curStart;
        }
    }

    cout << "a) Liczba serii malejacych: " << liczbaSerii << endl;
    cout << "b) Srednia dlugosc: " << fixed << setprecision(2)
         << (double)sumaDlugosci / liczbaSerii << endl;
    cout << "c) Najdluzsza seria: dlugosc " << maxDl
         << ", pozycja poczatkowa: " << maxStart + 1 << endl;
    return 0;
}
```

**Wyjasnienie**: Skanowanie liniowe ze sledzeniem biezacej serii malejacej. Gdy seria sie konczy (element nie mniejszy od poprzedniego) lub koniec tablicy, zamykamy serie i aktualizujemy statystyki.

Weryfikacja (dane: 10,8,5,3,7,9,6,4,12,11,8,2,15,13,20):
- 10,8,5,3 (dl.4, start=0): i=4: 7>3 -> zamkniecie. Serie=1, suma=4, max=4/start0.
- 7->9 rosnacy, curStart=5.
- 9,6,4 (dl.3, start=5): i=8: 12>4 -> zamkniecie. Serie=2, suma=7, max=4/start0.
- 12,11,8,2 (dl.4, start=8): i=12: 15>2 -> zamkniecie. Serie=3, suma=11, max=4/start0 (rowne, nie zmienia).
- 15,13 (dl.2, start=12): i=14: 20>13 -> zamkniecie. Serie=4, suma=13.
- Koniec: curDl=1, brak serii.

Wynik: 4 serie, suma=4+3+4+2=13, srednia=13/4=3.25, najdluzsza=4 od poz.1 (1-indeks).
